const geo=(k,fn)=>{if(!geoCache.has(k))geoCache.set(k,fn());return geoCache.get(k);};
const boxGeo=geo('box',()=>new T.BoxGeometry(1,1,1));
const sphereGeo=geo('sphere',()=>new T.IcosahedronGeometry(1,0));
function mesh(g,m,x=0,y=0,z=0,sx=1,sy=sx,sz=sx){const o=new T.Mesh(g,typeof m==='string'?mat(m):m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;return o;}
function box(parent,x,y,z,w,h,d,c){const m=mesh(boxGeo,c,x,y,z,w,h,d);parent.add(m);return m;}
function ball(parent,x,y,z,r,c,sy=r){const m=mesh(sphereGeo,c,x,y,z,r,sy,r);parent.add(m);return m;}
function cylinder(parent,x,y,z,r,h,c,sides=8){const g=geo('cyl'+sides,()=>new T.CylinderGeometry(1,1,1,sides));const m=mesh(g,c,x,y,z,r,h,r);parent.add(m);return m;}
