 this.attackRing.visible=!!game.showAttackRange&&!p.dead;this.attackRing.position.set(p.x,game.height(p)+.3,p.z);this.attackRing.scale.setScalar(game.attackRange(p));const locked=game.entities.find(e=>e.id===game.lockTarget&&!e.dead);this.lockRing.visible=!!locked;if(locked){this.lockRing.position.set(locked.x,game.height(locked)+.3,locked.z);this.lockRing.scale.setScalar(locked.r+1.1);}const danger=game.entities.find(e=>(e.kind==='tower'||e.kind==='core')&&e.team!==p.team&&e.team<2&&!e.dead&&dist(e,p)<e.range+6&&game.vulnerable(e));this.dangerRing.visible=!!danger;if(danger){this.dangerRing.position.set(danger.x,game.height(danger)+.24,danger.z);this.dangerRing.scale.setScalar(danger.range);this.dangerRing.material.opacity=danger.aggro===p.id&&danger.aggroUntil>game.time?.55:.2;}
