 let count=0;const getFx=(shape,color)=>{let o=this.fx[count];if(!o||o.userData.shape!==shape){if(o){this.dynamic.remove(o);o.material.dispose();}o=new T.Mesh(shape==='ring'?geo('fxring',()=>new T.RingGeometry(.88,1,32)):shape==='box'?boxGeo:sphereGeo,new T.MeshBasicMaterial({color,transparent:true,opacity:.7,side:T.DoubleSide,depthWrite:false}));o.userData.shape=shape;this.dynamic.add(o);this.fx[count]=o;}o.visible=true;o.material.color.set(color);o.material.opacity=.6;o.rotation.set(0,0,0);count++;return o;};
 this.vfx.update(game,dt,now);if(game.mode==='spike'&&game.spike){const s=game.spike;if(!this.spikeModel){this.spikeModel=new T.Group();cylinder(this.spikeModel,0,.55,0,.55,.8,'#536369',6);for(let i=-1;i<=1;i++){const a=box(this.spikeModel,i*.45,.7,0,.15,1.3,.6,'#b9d0c5');a.rotation.z=-i*.35;}ball(this.spikeModel,0,1.2,0,.3,'#8af4dc');this.dynamic.add(this.spikeModel);}this.spikeModel.visible=s.state==='dropped'||s.state==='planted';this.spikeModel.position.set(s.x,game.height(s),s.z);if(s.state==='planted'){const b=getFx('ring','#f2bc7d');b.rotation.x=-Math.PI/2;b.position.set(s.x,game.height(s)+.2,s.z);b.scale.setScalar(2+(now*1.8)%2);}}else if(this.spikeModel)this.spikeModel.visible=false;
 if(!this.lootModels)this.lootModels=new Map();const activeDrops=new Set();for(const drop of game.drops||[]){activeDrops.add(drop.id);let m=this.lootModels.get(drop.id);if(!m){m=new T.Group();const price=GUNS[drop.gun].price,c=price>=2400?'#e8c08d':price>=1000?'#b3b0e8':'#99cfbf';ring(m,0,.08,0,1.2,c,.75);box(m,0,.4,0,.22,.18,1.6,'#30454b');box(m,0,.3,-.25,.18,.5,.3,'#526d6c');box(m,0,.4,1,.09,.1,.5,c);this.dynamic.add(m);this.lootModels.set(drop.id,m);}m.position.set(drop.x,game.height(drop),drop.z);m.rotation.y=.6;if(dist(p,drop)<10){const sc=this.project(drop.x,game.height(drop)+1.2,drop.z);c.font='bold 10px system-ui';c.textAlign='center';c.fillStyle='#fff0c3';c.fillText(GUNS[drop.gun].name+' · X 拾取',sc.x,sc.y);}}for(const[id,m]of this.lootModels)if(!activeDrops.has(id)){this.dynamic.remove(m);this.lootModels.delete(id);}
