 minimap(game,canvas){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;const sx=w/160,sy=h/(game.heightBound||100);drawPlan(ctx,w,h);if(game.navigationEnabled&&game.navigation?.path.length){ctx.strokeStyle='#ffe1a0aa';ctx.lineWidth=1.6;ctx.setLineDash([3,3]);ctx.beginPath();ctx.moveTo(game.player.x*sx,game.player.z*sy);for(const p of game.navigation.path)ctx.lineTo(p.x*sx,p.z*sy);ctx.stroke();ctx.setLineDash([]);}for(const site of game.sites||[]){ctx.fillStyle='#eddaa5';ctx.font='bold 13px system-ui';ctx.textAlign='center';ctx.fillText(site.name,site.x*sx,site.z*sy);}for(const e of game.entities){if(e.dead||e.kind==='minion')continue;if(e.team===1&&game.mode==='spike'){const scanned=game.scanUntil?.[0]>game.time&&dist(e,game.player)<22;const visible=game.entities.some(a=>a.kind==='hero'&&a.team===0&&!a.dead&&dist(a,e)<24&&game.los(a,e));if(!scanned&&(!visible||game.status(e,'invis')))continue;}else if(game.status(e,'invis')&&e.team===1)continue;ctx.fillStyle=e.player?'#fff4bb':e.team===0?'#8fe5c2':e.team===1?'#ff9786':BUFFS[e.buff]?.color||'#d2b4ed';ctx.beginPath();ctx.arc(e.x*sx,e.z*sy,e.kind==='core'?4:e.kind==='tower'?2.7:e.player?3.8:2.3,0,Math.PI*2);ctx.fill();}if(game.mode==='spike'&&game.spike.state!=='carried'){ctx.fillStyle='#fff1bc';ctx.fillRect(game.spike.x*sx-2,game.spike.z*sy-2,4,4);}if(game.order&&game.order.kind!=='auto'){const o=game.order,loc=game.sites?.find(s=>s.name===o.kind)||(o.kind==='follow'?game.player:o);ctx.strokeStyle='#fff2ab';ctx.lineWidth=2;ctx.beginPath();ctx.arc(loc.x*sx,loc.z*sy,7,0,Math.PI*2);ctx.stroke();}ctx.strokeStyle='#ffffff60';ctx.lineWidth=1;ctx.strokeRect((game.player.x-23)*sx,(game.player.z-18)*sy,46*sx,36*sy);}
